SET @doc = '{"schema":"campus-nav/1","campus":{"name":"Main Campus","units":"meters","coordinates":"x = east, y = north on each floor plan; floor.northOffset (deg) rotates the plan to true compass north","qrFormat":"campus://F<floor>/<nodeId>"},"floors":[{"floor":1,"name":"Ground Floor","northOffset":0,"nodes":[{"id":"f1S","x":0,"y":0,"type":"stairs","label":"Stairs landing"},{"id":"f1A","x":12,"y":0,"type":"corridor","label":"Corridor A"},{"id":"f1B","x":24,"y":0,"type":"junction","label":"Corridor junction"},{"id":"f1C","x":24,"y":14,"type":"corridor","label":"Corridor C"},{"id":"f1D","x":24,"y":28,"type":"corridor","label":"Corridor end"}],"edges":[["f1S","f1A"],["f1A","f1B"],["f1B","f1C"],["f1C","f1D"]],"rooms":[{"id":"101","name":"Registrar Office","node":"f1A"},{"id":"102","name":"Computer Lab","node":"f1B"},{"id":"103","name":"Science Lab","node":"f1C"},{"id":"104","name":"Library","node":"f1D"}],"qr":[{"node":"f1S","payload":"campus://F1/f1S","label":"Ground Floor - Stairs landing"},{"node":"f1B","payload":"campus://F1/f1B","label":"Ground Floor - Corridor junction"}]},{"floor":2,"name":"Second Floor","northOffset":0,"nodes":[{"id":"f2S","x":0,"y":0,"type":"stairs","label":"Stairs landing"},{"id":"f2A","x":12,"y":0,"type":"corridor","label":"Corridor A"},{"id":"f2B","x":24,"y":0,"type":"junction","label":"Corridor junction"},{"id":"f2C","x":24,"y":14,"type":"corridor","label":"Corridor C"},{"id":"f2D","x":24,"y":28,"type":"corridor","label":"Corridor end"}],"edges":[["f2S","f2A"],["f2A","f2B"],["f2B","f2C"],["f2C","f2D"]],"rooms":[{"id":"201","name":"Lecture Hall A","node":"f2A"},{"id":"202","name":"Lecture Hall B","node":"f2B"},{"id":"203","name":"Physics Lab","node":"f2C"},{"id":"204","name":"Faculty Room","node":"f2D"}],"qr":[{"node":"f2S","payload":"campus://F2/f2S","label":"Second Floor - Stairs landing"},{"node":"f2B","payload":"campus://F2/f2B","label":"Second Floor - Corridor junction"}]},{"floor":3,"name":"Third Floor","northOffset":0,"nodes":[{"id":"f3S","x":0,"y":0,"type":"stairs","label":"Stairs landing"},{"id":"f3A","x":12,"y":0,"type":"corridor","label":"Corridor A"},{"id":"f3B","x":24,"y":0,"type":"junction","label":"Corridor junction"},{"id":"f3C","x":24,"y":14,"type":"corridor","label":"Corridor C"},{"id":"f3D","x":24,"y":28,"type":"corridor","label":"Corridor end"}],"edges":[["f3S","f3A"],["f3A","f3B"],["f3B","f3C"],["f3C","f3D"]],"rooms":[{"id":"301","name":"Seminar Room","node":"f3A"},{"id":"302","name":"Engineering Studio","node":"f3B"},{"id":"303","name":"Chemistry Lab","node":"f3C"},{"id":"304","name":"Dean''s Office","node":"f3D"}],"qr":[{"node":"f3S","payload":"campus://F3/f3S","label":"Third Floor - Stairs landing"},{"node":"f3B","payload":"campus://F3/f3B","label":"Third Floor - Corridor junction"}]}],"connectors":[{"type":"stairs","nodes":["f1S","f2S","f3S"],"cost":15}]}';
INSERT IGNORE INTO campuses (slug, name, data, version) VALUES ('main-campus', 'Main Campus', @doc, 1);
